begin;
insert into auth.users(id,email,email_confirmed_at)values('51000000-0000-4000-8000-000000000001','dataset@example.invalid',now());
insert into public.user_profiles(id)values('51000000-0000-4000-8000-000000000001');
insert into public.companies(id,name)values('51000000-0000-4000-8000-000000000011','Dataset fixture'),('51000000-0000-4000-8000-000000000012','Other tenant');
insert into public.user_company_roles(company_id,user_id,role)values('51000000-0000-4000-8000-000000000011','51000000-0000-4000-8000-000000000001','Super Admin');
set local role authenticated;
select set_config('request.jwt.claim.sub','51000000-0000-4000-8000-000000000001',true);
do $$declare c uuid:='51000000-0000-4000-8000-000000000011';p jsonb;e uuid;other_e uuid;run uuid;v integer;batch jsonb;snapshot jsonb;old_a uuid;begin
 p:='{"employeeCode":"DATA1","employeeName":"Dataset Employee","gender":"","dateOfBirth":"","maritalStatus":"","phone":"","aadhaar":"","pan":"","uan":"","esicNumber":"","joiningDate":"2026-05-01","exitDate":"","clientStatus":"Active","counterCode":"","counterName":"","reportingManager":"","workLocation":"","state":"","department":"IT","designation":"Software Developer","accountNumber":"","ifscCode":"","amounts":{"basic":1000000,"da":200000,"hra":300000,"other":100000},"salaryEffectiveFrom":"2026-05-01","salaryReference":{"grossMinor":1600000,"pfMinor":null,"esiMinor":null,"ctcMinor":null}}';
 perform public.import_employee_dataset(c,jsonb_build_array(p));
 select id,version into e,v from public.employees where company_id=c and employee_code='DATA1';
 old_a:=public.salary_assignment_at(c,e,'2026-05-01');
 if old_a is null then raise exception 'FAIL no dataset salary';end if;
 if exists(select 1 from public.designation_salary_presets where company_id=c)then raise exception 'FAIL seeded preset';end if;
 other_e:=public.save_employee(c,'{"employeeCode":"DATA2","firstName":"Second","lastName":"Employee","joiningDate":"2026-05-01","email":"","department":"IT","designation":"Software Developer"}');
 if public.salary_assignment_at(c,other_e,'2026-06-01')is not null then raise exception 'FAIL designation assigned salary';end if;
 if not exists(select 1 from jsonb_array_elements(public.validate_payroll(c,'2026-06-01')->'issues')i where i->>'employeeId'=other_e::text and i->>'check'='No Salary Assigned'and i->>'severity'='Blocking Error')then raise exception 'FAIL missing dataset not reported';end if;
 select version into v from public.employees where id=other_e;
 perform public.import_employee_dataset(c,jsonb_build_array(p||jsonb_build_object('employeeCode','DATA2','employeeName','Second Employee','amounts','{"basic":2000000,"da":400000,"hra":600000,"other":200000}'::jsonb,'salaryReference','{"grossMinor":3200000}'::jsonb)),true,jsonb_build_object('DATA2',v));
 begin perform public.import_employee_dataset(c,jsonb_build_array(p),true,'{"DATA1":999}');raise exception 'FAIL stale accepted';exception when serialization_failure then null;end;
 begin perform public.import_employee_dataset('51000000-0000-4000-8000-000000000012',jsonb_build_array(p));raise exception 'FAIL tenant accepted';exception when insufficient_privilege then null;end;
 begin perform public.import_employee_dataset(c,jsonb_build_array(p||'{"employeeCode":"BAD","amounts":{"basic":100}}'));raise exception 'FAIL incomplete accepted';exception when sqlstate 'P0051'then null;end;
 if exists(select 1 from public.employees where company_id=c and employee_code='BAD')then raise exception 'FAIL partial import';end if;
 select jsonb_agg(jsonb_build_object('employeeId',emp.id,'date',day::date,'status',case when emp.id=e and day::date='2026-06-02'then 'A'when day::date='2026-06-03'then 'L'when day::date='2026-06-07'then 'H'else 'P'end))into batch from public.employees emp cross join generate_series('2026-06-01'::date,'2026-06-30'::date,interval '1 day')day where emp.company_id=c;
 perform public.import_attendance(c,batch,'Dataset attendance fixture');perform public.finalize_attendance(c,'2026-06-01');
 run:=public.calculate_payroll(c,'2026-06-01');
 if not exists(select 1 from public.payroll_run_employees where run_id=run and employee_id=e and gross_minor=1546667 and net_minor=1546667)then raise exception 'FAIL DATA1 exact payroll';end if;
 if not exists(select 1 from public.payroll_run_employees where run_id=run and employee_id=other_e and gross_minor=3200000 and net_minor=3200000)then raise exception 'FAIL same role uses different dataset amounts';end if;
 select version into v from public.payroll_runs where id=run;
 perform public.transition_payroll(c,'2026-06-01','approve',v);perform public.transition_payroll(c,'2026-06-01','lock',v+1);
 select jsonb_agg(to_jsonb(r)order by employee_id)into snapshot from public.payroll_run_employees r where run_id=run;
 select version into v from public.employees where id=e;
 perform public.import_employee_dataset(c,jsonb_build_array(p||'{"salaryEffectiveFrom":"2026-07-01","amounts":{"basic":1100000,"da":200000,"hra":300000,"other":100000},"salaryReference":{"grossMinor":1700000}}'),true,jsonb_build_object('DATA1',v));
 if public.salary_assignment_at(c,e,'2026-06-30')<>old_a or public.salary_assignment_at(c,e,'2026-07-01')=old_a then raise exception 'FAIL revision dates';end if;
 if snapshot is distinct from(select jsonb_agg(to_jsonb(r)order by employee_id)from public.payroll_run_employees r where run_id=run)then raise exception 'FAIL locked payroll changed';end if;
 select version into v from public.employees where id=e;
 perform public.import_employee_dataset(c,jsonb_build_array(p||'{"salaryEffectiveFrom":"2026-07-01","amounts":{"basic":1100000,"da":200000,"hra":300000,"other":100000},"salaryReference":{"grossMinor":1700000}}'),true,jsonb_build_object('DATA1',v));
 if(select count(*)from public.employee_salary_assignments where company_id=c and employee_id=e)<>2 then raise exception 'FAIL repeated salary duplicated';end if;
end $$;
rollback;
